  {id="SpeedOnPickup", rich="Taking an item orb reward grants <em>+3%</> damage and <em>Movement Speed</> for <em>20 seconds</>, stacking up to <em>3</> (<em>+2</> per stack) times.", plain="Taking an item orb reward grants +3% damage and Movement Speed for 20 seconds, stacking up to 3 (+2 per stack) times.", pickup="Item orbs grant a stacking bonus to damage and movement speed."},
  {id="SprintArmor", rich="While moving fast, damage you take is reduced by <em>23%</> (more with stacks, with diminishing returns).", plain="While moving fast, damage you take is reduced by 23% (more with stacks, with diminishing returns).", pickup="Reduce incoming damage while sprinting."},
  {id="SprintOutOfCombat", rich="<em>+30%</> (<em>+30%</> per stack) <em>Movement Speed</> while <em>out of combat</>.", plain="+30% (+30% per stack) Movement Speed while out of combat.", pickup="Move fast out of combat."},
  {id="StrengthenBurn", rich="<img id=\"DamageType.Fire\"/><element_fire>Fire Damage</> that burns over time from your items (Gasoline, Kjaro's Band) deals <em>+300%</> (<em>+300%</> per stack) damage.", plain="Fire Damage that burns over time from your items (Gasoline, Kjaro's Band) deals +300% (+300% per stack) damage.", pickup="Your ignite effects deal quadruple damage."},
  {id="TPHealingNova", rich="When an encounter starts, heal yourself and allies within <em>30m</> for <em>50%</> of <img id=\"Stat.Health\"/><em>Maximum Health</>. Repeats <em>1</> (<em>+1</> per stack) times, <em>15 seconds</> apart.", plain="When an encounter starts, heal yourself and allies within 30m for 50% of Maximum Health. Repeats 1 (+1 per stack) times, 15 seconds apart.", pickup="Release a healing nova when an encounter starts."},
  {id="TeleportOnLowHealth", rich="Once per mission, dropping below <em>25%</> <img id=\"Stat.Health\"/><em>Health</> grants <img id=\"Stat.Shield\"/><em>Temporary Shield</> worth <em>30%</> of your <img id=\"Stat.Health\"/><em>Maximum Health</>. For the next <em>8 seconds</>, enemies within <em>10m</> take <em>100%</> of your average hit as <img id=\"DamageType.Nano\"/><element_nano>Nano Damage</> every second and are launched. Can <img id=\"Crit.CriticalHit\"/><em>Critical Hit</>.", plain="Once per mission, dropping below 25% Health grants Temporary Shield worth 30% of your Maximum Health. For the next 8 seconds, enemies within 10m take 100% of your average hit as Nano Damage every second and are launched. Can Critical Hit.", pickup="Gain a temporary shield and a dimensional aura on low health."},
  {id="TriggerEnemyDebuffs", rich="<em>10%</> chance on hit to deal <em>100%</> of your average hit as <img id=\"DamageType.Nano\"/><element_nano>Nano Damage</> over <em>2 seconds</>. Killing an enemy passes its <img id=\"Elemental\"/><em>Elemental Debuffs</> on to <em>1</> (<em>+1</> per stack) enemy within <em>20m</> (<em>+5m</> per stack). Can <img id=\"Crit.CriticalHit\"/><em>Critical Hit</>.", plain="10% chance on hit to deal 100% of your average hit as Nano Damage over 2 seconds. Killing an enemy passes its Elemental Debuffs on to 1 (+1 per stack) enemy within 20m (+5m per stack). Can Critical Hit.", pickup="Killing an enemy transfers debuffs to a nearby enemy."},
  {id="WarCryOnMultiKill", rich="Killing <em>4</> enemies within <em>1 second</> sends you into a frenzy for <em>6</> (<em>+4</> per stack) <em>seconds</>: <em>+50%</> <em>Movement Speed</> and <em>+100%</> <em>Fire Rate</>.", plain="Killing 4 enemies within 1 second sends you into a frenzy for 6 (+4 per stack) seconds: +50% Movement Speed and +100% Fire Rate.", pickup="Enter a frenzy after killing 4 enemies in quick succession."},
  {id="AlienHead", rich="Abilities recharge <em>33%</> faster (<em>+33%</> per stack, compounding).", plain="Abilities recharge 33% faster (+33% per stack, compounding).", pickup="Reduces cooldowns for your skills."},
  {id="ArmorReductionOnHit", rich="Every <em>5th</> hit on the same enemy applies <img id=\"Effect.Marked\"/><em>Mark</> for <em>8</> (<em>+8</> per stack) <em>seconds</>. <img id=\"Effect.Marked\"/><em>Marked</> enemies take <em>+50%</> damage.", plain="Every 5th hit on the same enemy applies Mark for 8 (+8 per stack) seconds. Marked enemies take +50% damage.", pickup="Mark enemies after repeatedly striking them."},
  {id="BarrierOnOverHeal", rich="Healing past full <img id=\"Stat.Health\"/><em>Health</> grants <img id=\"Stat.Shield\"/><em>Temporary Shield</> worth <em>50%</> (<em>+50%</> per stack) of the extra healing.", plain="Healing past full Health grants Temporary Shield worth 50% (+50% per stack) of the extra healing.", pickup="Healing past full grants you a temporary shield."},
  {id="BoostAllStats", rich="<em>+4%</> damage and <em>Fire Rate</> for each active item buff, up to <em>4</> (<em>+4</> per stack) buffs.", plain="+4% damage and Fire Rate for each active item buff, up to 4 (+4 per stack) buffs.", pickup="Your buffs increase your damage and attack speed."},
  {id="Clover", rich="Item effects that rely on chance roll <em>1</> (<em>+1</> per stack) extra time for a favourable outcome.", plain="Item effects that rely on chance roll 1 (+1 per stack) extra time for a favourable outcome.", pickup="Luck is on your side."},
  {id="CritDamage", rich="<em>+35%</> (<em>+35%</> per stack) <img id=\"Crit.CritDamage\"/><em>Crit Damage</>.", plain="+35% (+35% per stack) Crit Damage.", pickup="Your 'Critical Strikes' deal more damage."},
  {id="Duplicator", rich="Taking an item from an item orb also grants a temporary copy of it for <em>10</> (<em>+10</> per stack) <em>seconds</>.", plain="Taking an item from an item orb also grants a temporary copy of it for 10 (+10 per stack) seconds.", pickup="Picking up an item grants a temporary copy."},
  {id="FallBoots", rich="<em>+30%</> (<em>+30%</> per stack) jump height. Landing after falling at least <em>4m</> releases a kinetic blast of <img id=\"DamageType.Psionic\"/><element_Psionic>Psionic Damage</> that grows with the fall height. (<em>10 second</> cooldown, halved per stack) Can <img id=\"Crit.CriticalHit\"/><em>Critical Hit</>.", plain="+30% (+30% per stack) jump height. Landing after falling at least 4m releases a kinetic blast of Psionic Damage that grows with the fall height. (10 second cooldown, halved per stack) Can Critical Hit.", pickup="Increase jump height. Landing from a great height creates a kinetic blast."},
  {id="Icicle", rich="Killing an enemy surrounds you with an ice storm for <em>6 seconds</> that deals <em>60%</> of your average hit as <img id=\"DamageType.Cryo\"/><element_cryo>Cryo Damage</> every <em>0.5 seconds</>, applying <img id=\"Element.Cryo.Chill\"/><element_cryo>Chill</>. Each kill grows it by <em>2m</>, up to <em>18m</> (<em>+12m</> per stack). Can <img id=\"Crit.CriticalHit\"/><em>Critical Hit</>.", plain="Killing an enemy surrounds you with an ice storm for 6 seconds that deals 60% of your average hit as Cryo Damage every 0.5 seconds, applying Chill. Each kill grows it by 2m, up to 18m (+12m per stack). Can Critical Hit.", pickup="Killing enemies surrounds you with an ice storm."},
  {id="IncreaseHealing", rich="All healing is <em>+100%</> (<em>+100%</> per stack) stronger, including <em>Health Orbs</>.", plain="All healing is +100% (+100% per stack) stronger, including Health Orbs.", pickup="Double the strength of healing."},
  {id="KillEliteFrenzy", rich="Killing an <img id=\"EnemyType.Elite\"/><em>Elite</> enemy sends you into a frenzy for <em>4</> (<em>+4</> per stack) <em>seconds</>: abilities recharge <em>10x</> faster.", plain="Killing an Elite enemy sends you into a frenzy for 4 (+4 per stack) seconds: abilities recharge 10x faster.", pickup="Skills recharge rapidly for a short period after killing an elite."},
  {id="PermanentDebuffOnHit", rich="Each hit permanently makes that enemy take <em>+2%</> (<em>+2%</> per stack) more damage from you, up to <em>+50%</>.", plain="Each hit permanently makes that enemy take +2% (+2% per stack) more damage from you, up to +50%.", pickup="Enemies you hit permanently take more damage from you."},
  {id="Plant", rich="Killing an enemy plants a seed that sprouts after <em>5 seconds</>. For <em>10 seconds</> it heals you and allies within <em>5m</> (<em>+5m</> per stack) for <em>10%</> of <img id=\"Stat.Health\"/><em>Maximum Health</> every second.", plain="Killing an enemy plants a seed that sprouts after 5 seconds. For 10 seconds it heals you and allies within 5m (+5m per stack) for 10% of Maximum Health every second.", pickup="Plant a healing fruit on kill."},
  {id="SharedSuffering", rich="Hits infect up to <em>4</> (<em>+2</> per stack) enemies with <img id=\"Element.Void.Corruption\"/><element_void>Corruption</>. <em>45%</> of all damage you deal to infected enemies is pooled, and every <em>3 seconds</> each infected enemy takes the pool as <img id=\"DamageType.Void\"/><element_void>Void Damage</>. Can <img id=\"Crit.CriticalHit\"/><em>Critical Hit</>.", plain="Hits infect up to 4 (+2 per stack) enemies with Corruption. 45% of all damage you deal to infected enemies is pooled, and every 3 seconds each infected enemy takes the pool as Void Damage. Can Critical Hit.", pickup="Inflict a computer virus on hit that spreads a portion of all damage dealt between infected enemies. Affects up to 4 enemies."},
  {id="ShockNearby", rich="Every <em>0.5 seconds</>, zap <em>3</> (<em>+2</> per stack) enemies within <em>35m</> for <em>200%</> of your average hit as <img id=\"DamageType.Lightning\"/><element_lightning>Lightning Damage</>, applying <img id=\"Element.Lightning.Shock\"/><element_lightning>Shock</>. Switches on and off every <em>10 seconds</>. Can <img id=\"Crit.CriticalHit\"/><em>Critical Hit</>.", plain="Every 0.5 seconds, zap 3 (+2 per stack) enemies within 35m for 200% of your average hit as Lightning Damage, applying Shock. Switches on and off every 10 seconds. Can Critical Hit.", pickup="Shock nearby enemies. Turns on and off every 10 seconds."},
  {id="Talisman", rich="Killing an enemy makes abilities recharge <em>11%</> faster for <em>4</> (<em>+2</> per stack) <em>seconds</>, stacking up to <em>5</> times.", plain="Killing an enemy makes abilities recharge 11% faster for 4 (+2 per stack) seconds, stacking up to 5 times.", pickup="Kills make your abilities recharge faster."},
  {id="UtilitySkillMagazine", rich="Dash recharges <em>50%</> faster (<em>+50%</> per stack, compounding). <em>+10%</> (<em>+10%</> per stack) <em>Sprint Speed</>.", plain="Dash recharges 50% faster (+50% per stack, compounding). +10% (+10% per stack) Sprint Speed.", pickup="Your dash recharges faster."},
